export interface ForeignIdiomDoc {
  syntax: string
  instead: string
}

export const FOREIGN_IDIOMS: ForeignIdiomDoc[] = [
  {
    "syntax": "class= / class:<name>",
    "instead": "class: is retired — styling is a tag-position style({…}) / style(name) / style(partial, …) call on the element"
  },
  {
    "syntax": "style= / style:<prop>",
    "instead": "runtime geometry is owned by named, typed actions; paint is a tag-position style({…}) call, not an HTML style attribute"
  },
  {
    "syntax": "part=\"…\"",
    "instead": "style with a tag-position style({…}) call on the element itself — light DOM has no shadow parts"
  },
  {
    "syntax": "<div> / <span> for layout structure",
    "instead": "layout keywords <column>, <row>, <grid>, <stack>, <center> with axis attrs (gap, align, justify); participation is style({ grow(1).size({ min-w: 0 }) })"
  },
  {
    "syntax": "document.querySelector / getElementById in a controller",
    "instead": "a local use: action that captures the node on mount (and clears on destroy), or closed-over state + on: handlers — controllers do not reach into the DOM by selector"
  },
  {
    "syntax": "padding / padding-*",
    "instead": "pad(3) / pad({ x: 3, y: 2 }) — not a CSS padding property"
  },
  {
    "syntax": "font-size",
    "instead": "type(body-sm) — not a CSS font-size property"
  },
  {
    "syntax": "border-width",
    "instead": "border({ width: 1 }) — not a CSS border-width property"
  },
  {
    "syntax": "p-4 / text-sm",
    "instead": "pad(4) / type(body-sm) — not a Tailwind utility class"
  }
]

